  and timeline_root = #{timelineRoot}

select id, tenant_id, app_id, user_id, timeline_root, content_text, searchable, fragment_type, visibility, time_bucket, topic_tags, emotion_tags, chunk_seq, chunk_confidence, chunk_strategy, deleted, created_at from memory_fragment where tenant_id = #{tenantId} and app_id = #{appId} and user_id = #{userId} and deleted = false
and timeline_root = #{timelineRoot}
order by created_at desc, id desc limit #{limit} offset #{offset}
